WITH src AS (SELECT *, CASE WHEN status IN ('SUCCESS', 'FAILED') THEN 'Tier 1' ELSE 'Other' END AS status_group FROM payments WHERE amount IS NULL AND order_id IN (17, 29)), summary AS (SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, SUM(CASE WHEN method = 'card' THEN 1 ELSE 0 END) AS card_count FROM src GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT paid_cohort, card_count FROM summary;
